    for (size_t i = 0; i < 3; i++) {
        for (size_t j = 0; j < 3; j++) {
            diff = repaired->m[i][j] - candidate->m[i][j];
            d += diff * diff;
        }
    }
    *correction_norm = sqrt(d);

    return ADCS_OK;
}
